1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Filament\Resources\Products\Schemas;
6	
7	use App\Models\Category2;
8	use App\Models\Environment;
9	use App\Models\Material;
10	use App\Models\Product;
11	use App\Models\ProductType;
12	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
13	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\AttributesEditor;
14	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\NameAndId;
15	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\OrphanAttributesAlert;
16	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
17	use AtrioTeam\DigitalHub\Tags\Filament\TagPicker;
18	use Filament\Forms\Components\Select;
19	use Filament\Schemas\Components\Utilities\Get;
20	use Filament\Schemas\Schema;
21	
22	class ProductForm
23	{
24	    public static function configure(Schema $schema): Schema
25	    {
26	        return $schema
27	            ->components([
28	                NameAndId::make($schema),
29	                Select::make('category_2_id')
30	                    ->label(__('product.category_2'))
31	                    ->options(fn (): array => Category2::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
32	                    ->default(fn (): mixed => request()->query('category_2'))
33	                    ->required()
34	                    ->searchable(),
35	                Select::make('product_type_id')
36	                    ->label(__('product.product_type'))
37	                    ->options(fn (): array => ProductType::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
38	                    ->required()
39	                    ->searchable()
40	                    // reattivo: il cambio di tipologia rigenera l'editor degli attributi
41	                    // e (ri)valuta l'alert orfani sottostante
42	                    ->live(),
43	                Select::make('materials')
44	                    ->label(__('material.model_plural'))
45	                    ->relationship('materials', 'name')
46	                    ->options(fn (): array => Material::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
47	                    ->multiple()
48	                    ->searchable()
49	                    ->preload(),
50	                Select::make('environments')
51	                    ->label(__('product.environments'))
52	                    ->relationship('environments', 'name')
53	                    ->options(fn (): array => Environment::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
54	                    ->multiple()
55	                    ->searchable()
56	                    ->preload(),
57	                // solo i tag dei gruppi (product, entity) — vincolo rigido
58	                TagPicker::make((new Product())->getMorphClass(), TagTarget::Entity),
59	                // alert orfani: avvisa, al cambio tipologia, dei valori PIM che si
60	                // perderebbero perché non più previsti dal nuovo schema (vedi core).
61	                OrphanAttributesAlert::reactive($schema, self::schemaResolver()),
62	                AttributesEditor::reactive($schema, self::schemaResolver())->columnSpanFull()->columns(1),
63	            ]);
64	    }
65	
66	    /**
67	     * Resolver dello schema attributi corrente dal form state: legge
68	     * product_type_id e ritorna la AttributeSchema della tipologia selezionata
69	     * (o null). Condiviso da AttributesEditor::reactive() e OrphanAttributesAlert.
70	     *
71	     * @return \Closure(Get): ?AttributeSchema
72	     */
73	    private static function schemaResolver(): \Closure
74	    {
75	        return static function (Get $get): ?AttributeSchema {
76	            $class = self::schemaClassFor($get('product_type_id'));
77	
78	            return $class !== null ? new $class() : null;
79	        };
80	    }
81	
82	    /**
83	     * FQN della AttributeSchema associata a una tipologia, o null se non risolvibile.
84	     *
85	     * @return class-string<AttributeSchema>|null
86	     */
87	    private static function schemaClassFor(mixed $productTypeId): ?string
88	    {
89	        if (! is_numeric($productTypeId)) {
90	            return null;
91	        }
92	
93	        $class = ProductType::query()->find((int) $productTypeId)?->attribute_schema_class;
94	
95	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
96	    }
97	}
